//! PowerShell's own message text, copied from upstream's neutral resources.
//!
//! The catalog is generated by `scripts/gen-messages.py` from the neutral
//! `.resx` files of the latest stable PowerShell release, not typed by hand.
//! Its keys are
//! `"<resource set>/<name>"`, as in
//! `"CommandLineParameterParserStrings/MissingCommandParameter"`.
//!
//! The table is sorted and read with a binary search, so a message costs
//! nothing until the code that prints it asks for one. Placeholders go
//! through [`format`], which follows .NET's composite formatting for string
//! arguments: `{index[,alignment][:formatString]}`, `{{` and `}}` for literal
//! braces, and a format string that a string argument ignores.

mod catalog;

/// One catalog entry, for tests and tools that need to see the whole table.
pub fn entries() -> impl Iterator<Item = (&'static str, &'static str)> {
    catalog::CATALOG.iter().copied()
}

/// How many messages the catalog holds.
pub fn len() -> usize {
    catalog::CATALOG.len()
}

/// The text of the message `key` holds, or `None` if the catalog has no such
/// key. `key` is `"<resource set>/<name>"`.
pub fn get(key: &str) -> Option<&'static str> {
    catalog::CATALOG
        .binary_search_by(|entry| entry.0.cmp(key))
        .ok()
        .map(|index| catalog::CATALOG[index].1)
}

/// The text of the message `key` holds.
///
/// # Panics
///
/// Panics if the catalog has no such key. The keys rpsh uses are fixed
/// strings checked by the tests, so a missing one is a programming error,
/// not an input error.
pub fn text(key: &str) -> &'static str {
    get(key).unwrap_or_else(|| panic!("rpsh-messages: no message named {key:?}"))
}

/// The text of `key` with `args` substituted.
///
/// # Panics
///
/// Panics if the key is missing or the template does not accept `args`. The
/// same reasoning as [`text`] applies.
pub fn format(key: &str, args: &[&str]) -> String {
    render(text(key), args).unwrap_or_else(|error| panic!("rpsh-messages: {key:?}: {error}"))
}

/// Substitutes `args` into `template` the way .NET's `string.Format` does for
/// string arguments.
///
/// `.NET` ignores the `formatString` of an argument that does not implement
/// `IFormattable`, and `String` does not, so `{0:F2}` and `{0}` both print the
/// string unchanged. Numeric arguments will need the formatting rules from
/// the number work; the host's messages only take strings today.
pub fn render(template: &str, args: &[&str]) -> Result<String, FormatError> {
    let mut out = String::with_capacity(template.len());
    let mut chars = template.char_indices().peekable();
    while let Some((offset, ch)) = chars.next() {
        match ch {
            '{' => {
                if matches!(chars.peek(), Some(&(_, '{'))) {
                    chars.next();
                    out.push('{');
                    continue;
                }
                render_item(&mut chars, offset, args, &mut out)?;
            }
            '}' => {
                if matches!(chars.peek(), Some(&(_, '}'))) {
                    chars.next();
                    out.push('}');
                } else {
                    return Err(FormatError::new(offset, "unexpected '}'"));
                }
            }
            _ => out.push(ch),
        }
    }
    Ok(out)
}

/// Why a composite format string could not be rendered.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FormatError {
    /// Byte offset in the template where the problem was found.
    pub offset: usize,
    /// What the parser expected there.
    pub expected: &'static str,
}

impl FormatError {
    fn new(offset: usize, expected: &'static str) -> Self {
        Self { offset, expected }
    }
}

impl std::fmt::Display for FormatError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} at offset {}", self.expected, self.offset)
    }
}

impl std::error::Error for FormatError {}

fn render_item(
    chars: &mut std::iter::Peekable<std::str::CharIndices<'_>>,
    open: usize,
    args: &[&str],
    out: &mut String,
) -> Result<(), FormatError> {
    let index = parse_number(chars, open)?;
    skip_spaces(chars);

    // .NET's grammar is `{index[,alignment][:formatString]}`. A space after
    // the index or alignment is allowed; a sign is allowed only on the
    // alignment.
    let alignment = if matches!(chars.peek(), Some(&(_, ','))) {
        chars.next();
        skip_spaces(chars);
        let negative = matches!(chars.peek(), Some(&(_, '-')));
        if negative {
            chars.next();
        }
        let width = parse_number(chars, open)?;
        skip_spaces(chars);
        let width =
            i64::try_from(width).map_err(|_| FormatError::new(open, "alignment is too large"))?;
        if negative { -width } else { width }
    } else {
        0
    };

    if matches!(chars.peek(), Some(&(_, ':'))) {
        chars.next();
        loop {
            match chars.next() {
                Some((_, '}')) => break,
                Some(_) => {}
                None => return Err(FormatError::new(open, "format item ends prematurely")),
            }
        }
    } else {
        match chars.next() {
            Some((_, '}')) => {}
            Some(_) | None => {
                return Err(FormatError::new(open, "format item ends prematurely"));
            }
        }
    }

    let Some(arg) = args.get(index) else {
        return Err(FormatError::new(open, "index out of range"));
    };
    write_aligned(out, arg, alignment);
    Ok(())
}

fn parse_number(
    chars: &mut std::iter::Peekable<std::str::CharIndices<'_>>,
    open: usize,
) -> Result<usize, FormatError> {
    let start = chars.peek().map_or(open, |(offset, _)| *offset);
    let mut value = 0usize;
    let mut digits = 0usize;
    while let Some(&(_, ch)) = chars.peek() {
        let Some(digit) = ch.to_digit(10) else {
            break;
        };
        chars.next();
        digits += 1;
        value = value
            .checked_mul(10)
            .and_then(|rest| rest.checked_add(digit as usize))
            .ok_or_else(|| FormatError::new(start, "number is too large"))?;
    }
    if digits == 0 {
        return Err(FormatError::new(start, "expected an ASCII digit"));
    }
    Ok(value)
}

fn skip_spaces(chars: &mut std::iter::Peekable<std::str::CharIndices<'_>>) {
    while matches!(chars.peek(), Some(&(_, ch)) if ch.is_ascii_whitespace()) {
        chars.next();
    }
}

fn write_aligned(out: &mut String, arg: &str, alignment: i64) {
    // .NET measures a string in UTF-16 code units, so an emoji occupies two
    // columns' worth of padding.
    let width = alignment.unsigned_abs() as usize;
    let length = arg.encode_utf16().count();
    let pad = width.saturating_sub(length);
    if alignment < 0 {
        out.push_str(arg);
        out.extend(std::iter::repeat_n(' ', pad));
    } else {
        out.extend(std::iter::repeat_n(' ', pad));
        out.push_str(arg);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const MISSING_COMMAND_PARAMETER: &str =
        "CommandLineParameterParserStrings/MissingCommandParameter";
    const MISSING_FILE_ARGUMENT: &str = "CommandLineParameterParserStrings/MissingFileArgument";
    const ARGUMENT_FILE_DOES_NOT_EXIST: &str =
        "CommandLineParameterParserStrings/ArgumentFileDoesNotExist";

    #[test]
    fn the_catalog_is_sorted_and_has_no_duplicate_keys() {
        let mut previous = None;
        for (key, text) in entries() {
            assert!(!key.is_empty());
            assert!(!text.is_empty(), "{key}");
            if let Some(previous) = previous {
                assert!(previous < key, "out of order: {previous} then {key}");
            }
            previous = Some(key);
        }
        assert!(len() > 4_000, "only {} messages", len());
    }

    #[test]
    fn the_host_messages_are_in_the_catalog() {
        assert_eq!(
            text(MISSING_COMMAND_PARAMETER),
            "Cannot process the command because of a missing parameter. \
             A command must follow -Command."
        );
        assert_eq!(
            text(MISSING_FILE_ARGUMENT),
            "The command cannot be run because the File parameter requires a file \
             path. Supply a path for the File parameter and then try the command again."
        );
        assert_eq!(
            text(ARGUMENT_FILE_DOES_NOT_EXIST),
            "The argument '{0}' is not recognized as the name of a script file. \
             Check the spelling of the name, or if a path was included, verify \
             that the path is correct and try again."
        );
    }

    #[test]
    fn substitutes_a_string_argument() {
        assert_eq!(
            format(ARGUMENT_FILE_DOES_NOT_EXIST, &["missing.ps1"]),
            "The argument 'missing.ps1' is not recognized as the name of a script file. \
             Check the spelling of the name, or if a path was included, verify \
             that the path is correct and try again."
        );
    }

    #[test]
    fn escapes_braces_and_ignores_a_string_format_specifier() {
        assert_eq!(render("{{x}} {0:F2}", &["y"]).unwrap(), "{x} y");
        assert_eq!(render("{{{0}}}", &["y"]).unwrap(), "{y}");
    }

    #[test]
    fn aligns_like_dotnet() {
        assert_eq!(
            render("[{0,6}][{1,-6}]", &["ab", "cd"]).unwrap(),
            "[    ab][cd    ]"
        );
        assert_eq!(
            render("[{0, -3}][{1, 3 }]", &["x", "y"]).unwrap(),
            "[x  ][  y]"
        );
        assert_eq!(render("[{0,03}]", &["x"]).unwrap(), "[  x]");
        assert_eq!(render("[{0,3}]", &["\u{1F600}"]).unwrap(), "[ \u{1F600}]");
    }

    #[test]
    fn accepts_whitespace_after_the_index() {
        assert_eq!(render("{0 }", &["x"]).unwrap(), "x");
        assert_eq!(render("{0 , -3}", &["x"]).unwrap(), "x  ");
        assert_eq!(render("{0 :F2}", &["x"]).unwrap(), "x");
    }

    #[test]
    fn rejects_malformed_items_the_way_dotnet_does() {
        for template in [
            "{}", "{ 0}", "{-1}", "{0", "{0,}", "{0,+3}", "{0, - 3}", "{0,-3x}", "}", "{0}}",
        ] {
            assert!(render(template, &["x"]).is_err(), "{template:?}");
        }
        assert!(render("{1}", &["x"]).is_err());
    }

    #[test]
    fn an_empty_format_string_is_allowed() {
        assert_eq!(render("{0:}", &["x"]).unwrap(), "x");
    }
}
